/* eslint-disable @typescript-eslint/ban-ts-comment */
import { vi } from 'vitest'
import { encodeBase64, encodeBase64Url } from '../encode'
import { AlgorithmTypes } from './jwa'
import type { HonoJsonWebKey } from './jws'
import { signing } from './jws'
import * as JWT from './jwt'
import { verifyWithJwks } from './jwt'
import {
  JwtAlgorithmMismatch,
  JwtAlgorithmNotAllowed,
  JwtAlgorithmNotImplemented,
  JwtAlgorithmRequired,
  JwtHeaderInvalid,
  JwtPayloadRequiresAud,
  JwtSymmetricAlgorithmNotAllowed,
  JwtTokenAudience,
  JwtTokenExpired,
  JwtTokenInvalid,
  JwtTokenIssuedAt,
  JwtTokenIssuer,
  JwtTokenNotBefore,
  JwtTokenSignatureMismatched,
} from './types'
import { utf8Encoder } from './utf8'

describe('isTokenHeader', () => {
  it('should return true for valid TokenHeader', () => {
    const validTokenHeader: JWT.TokenHeader = {
      alg: AlgorithmTypes.HS256,
      typ: 'JWT',
    }

    expect(JWT.isTokenHeader(validTokenHeader)).toBe(true)
  })

  it('should return false for invalid TokenHeader', () => {
    const invalidTokenHeader = {
      alg: 'invalid',
      typ: 'JWT',
    }

    expect(JWT.isTokenHeader(invalidTokenHeader)).toBe(false)
  })

  it('returns true even if the typ field is absent in a TokenHeader', () => {
    const validTokenHeader: JWT.TokenHeader = {
      alg: AlgorithmTypes.HS256,
    }

    expect(JWT.isTokenHeader(validTokenHeader)).toBe(true)
  })

  it('returns false when the typ field is present but empty', () => {
    const invalidTokenHeader = {
      alg: AlgorithmTypes.HS256,
      typ: '',
    }

    expect(JWT.isTokenHeader(invalidTokenHeader)).toBe(false)
  })

  it('accepts JWT in any case, with or without the application/ prefix, by default', () => {
    for (const typ of ['JWT', 'jwt', 'application/jwt', 'Application/JWT']) {
      expect(JWT.isTokenHeader({ alg: AlgorithmTypes.HS256, typ })).toBe(true)
    }
  })

  it('rejects another typ by default', () => {
    for (const typ of ['at+jwt', 'application/at+jwt', 'JWT ', 1, null]) {
      expect(JWT.isTokenHeader({ alg: AlgorithmTypes.HS256, typ })).toBe(false)
    }
  })

  it('accepts only the expected typ when one is given', () => {
    for (const typ of ['at+jwt', 'AT+JWT', 'application/at+jwt']) {
      expect(JWT.isTokenHeader({ alg: AlgorithmTypes.HS256, typ }, 'at+jwt')).toBe(true)
    }
    expect(JWT.isTokenHeader({ alg: AlgorithmTypes.HS256, typ: 'JWT' }, 'at+jwt')).toBe(false)
    expect(JWT.isTokenHeader({ alg: AlgorithmTypes.HS256 }, 'at+jwt')).toBe(false)
  })

  it('accepts any of several expected typ values', () => {
    const expected = ['JWT', 'at+jwt']
    expect(JWT.isTokenHeader({ alg: AlgorithmTypes.HS256, typ: 'at+jwt' }, expected)).toBe(true)
    expect(JWT.isTokenHeader({ alg: AlgorithmTypes.HS256, typ: 'JWT' }, expected)).toBe(true)
    expect(JWT.isTokenHeader({ alg: AlgorithmTypes.HS256, typ: 'secevent+jwt' }, expected)).toBe(
      false
    )
  })
})

describe('JWT', () => {
  it('JwtAlgorithmNotImplemented', async () => {
    const payload = { message: 'hello world' }
    const secret = 'a-secret'
    const alg = ''
    let tok = ''
    let err: JwtAlgorithmNotImplemented
    try {
      tok = await JWT.sign(payload, secret, alg as AlgorithmTypes)
    } catch (e) {
      err = e as JwtAlgorithmNotImplemented
    }
    expect(tok).toBe('')
    // @ts-ignore
    expect(err).toEqual(new JwtAlgorithmNotImplemented(alg))
  })

  it('JwtTokenInvalid', async () => {
    const tok = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJtZXNzYWdlIjoiaGVsbG8gd29ybGQifQ'
    const secret = 'a-secret'
    let err: JwtTokenInvalid
    let authorized
    try {
      authorized = await JWT.verify(tok, secret, AlgorithmTypes.HS256)
    } catch (e) {
      err = e as JwtTokenInvalid
    }
    // @ts-ignore
    expect(err).toEqual(new JwtTokenInvalid(tok))
    expect(authorized).toBeUndefined()
  })

  it('JwtTokenInvalid for a signature that is not valid base64url', async () => {
    const tok = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJtZXNzYWdlIjoiaGVsbG8gd29ybGQifQ.@@@@'
    const err = await JWT.verify(tok, 'a-secret', AlgorithmTypes.HS256).catch((e: unknown) => e)
    expect(err).toBeInstanceOf(JwtTokenInvalid)
    expect(err).toHaveProperty('message', `invalid JWT token: ${tok}`)
  })

  it('JwtTokenInvalid for a signature containing whitespace', async () => {
    const secret = 'a-secret'
    const tok = await JWT.sign({ message: 'hello world' }, secret)
    expect(await JWT.verify(tok, secret, AlgorithmTypes.HS256)).toEqual({ message: 'hello world' })
    for (const malformed of [
      `${tok}\n`,
      `${tok} `,
      `${tok}\t`,
      `${tok.slice(0, -1)} ${tok.slice(-1)}`,
    ]) {
      const err = await JWT.verify(malformed, secret, AlgorithmTypes.HS256).catch((e: unknown) => e)
      expect(err).toBeInstanceOf(JwtTokenInvalid)
    }
  })

  it('JwtHeaderInvalid for a header with crit', async () => {
    const secret = 'a-secret'
    const encode = (s: string) => encodeBase64Url(utf8Encoder.encode(s).buffer).replace(/=/g, '')
    const signingInput = `${encode('{"alg":"HS256","typ":"JWT","crit":["exp"],"exp":1}')}.${encode('{"message":"hello"}')}`
    const signature = await signing(secret, AlgorithmTypes.HS256, utf8Encoder.encode(signingInput))
    const tok = `${signingInput}.${encodeBase64Url(signature).replace(/=/g, '')}`
    const err = await JWT.verify(tok, secret, AlgorithmTypes.HS256).catch((e: unknown) => e)
    expect(err).toBeInstanceOf(JwtHeaderInvalid)
  })

  describe('typ', () => {
    const secret = 'a-secret'
    const makeToken = async (typ: string) => {
      const encode = (s: string) => encodeBase64Url(utf8Encoder.encode(s).buffer).replace(/=/g, '')
      const signingInput = `${encode(JSON.stringify({ alg: 'HS256', typ }))}.${encode('{"message":"hello"}')}`
      const signature = await signing(
        secret,
