describe('verifyWithJwks typ', () => {
  it('Should enforce the expected typ from verification options', async () => {
    const payload = { message: 'hello world' }
    const kid = 'dummy'
    const keyPair = await crypto.subtle.generateKey(
      {
        name: 'RSASSA-PKCS1-v1_5',
        modulusLength: 2048,
        publicExponent: new Uint8Array([1, 0, 1]),
        hash: 'SHA-256',
      },
      true,
      ['sign', 'verify']
    )

    const encode = (obj: object) => encodeBase64Url(utf8Encoder.encode(JSON.stringify(obj)).buffer)
    const makeToken = async (typ: string) => {
      const signingInput = `${encode({ alg: 'RS256', typ, kid })}.${encode(payload)}`
      const signatureBuffer = await signing(
        keyPair.privateKey,
        'RS256',
        utf8Encoder.encode(signingInput)
      )
      return `${signingInput}.${encodeBase64Url(signatureBuffer)}`
    }

    const jwk = await crypto.subtle.exportKey('jwk', keyPair.publicKey)
    const keys = [{ ...jwk, kid, use: 'sig', alg: 'RS256' }]

    const accessToken = await makeToken('at+jwt')
    const plainJwt = await makeToken('JWT')

    await expect(verifyWithJwks(accessToken, { keys, allowedAlgorithms: ['RS256'] })).rejects.toThrow(
      JwtHeaderInvalid
    )
    await expect(
      verifyWithJwks(accessToken, {
        keys,
        allowedAlgorithms: ['RS256'],
        verification: { typ: 'at+jwt' },
      })
    ).resolves.toEqual(payload)
    await expect(
      verifyWithJwks(plainJwt, {
        keys,
        allowedAlgorithms: ['RS256'],
        verification: { typ: 'at+jwt' },
      })
    ).rejects.toThrow(JwtHeaderInvalid)
  })
})

